using System;using System.IO;using System.Globalization;public class Metrics{public static void Run(string p,int seconds){double[] id=new double[20],iq=new double[20],refq=new double[20],min=new double[20],max=new double[20],last=new double[20];int[] n=new int[20];for(int j=0;j<20;j++){min[j]=1e9;max[j]=-1e9;}foreach(var l in File.ReadLines(p)){if(l.StartsWith("time"))continue;var s=l.Split(',');int k=int.Parse(s[8]);double t=double.Parse(s[0],CultureInfo.InvariantCulture),v=double.Parse(s[1],CultureInfo.InvariantCulture),target=double.Parse(s[9],CultureInfo.InvariantCulture);min[k]=Math.Min(min[k],v);max[k]=Math.Max(max[k],v);if(Math.Abs(v-target)>Math.Max(10,Math.Abs(target)*.02))last[k]=t-k*seconds;if(t>=k*seconds+seconds*.5){n[k]++;id[k]+=double.Parse(s[3],CultureInfo.InvariantCulture);iq[k]+=double.Parse(s[4],CultureInfo.InvariantCulture);refq[k]+=double.Parse(s[2],CultureInfo.InvariantCulture);}}for(int k=0;k<20;k++)if(n[k]>0)Console.WriteLine("stage="+k+" min="+min[k].ToString("F1")+" max="+max[k].ToString("F1")+" settle2pct="+last[k].ToString("F3")+" Id_mean="+(id[k]/n[k]).ToString("F2")+" Iq_mean="+(iq[k]/n[k]).ToString("F2")+" Iqref_mean="+(refq[k]/n[k]).ToString("F2"));}}